import json,re,glob,sys
used=set()
for f in glob.glob('Lamsa/Sources/*.swift'): used|=set(re.findall(r'L\("([A-Za-z0-9._]+)"\)',open(f).read()))
used|={"kind."+k for k in "text url phone sms email wifi contact location app shortcut custom qr".split()}
miss=used-set(S); assert not miss, miss
cat={"sourceLanguage":"ar","version":"1.0","strings":{k:{"extractionState":"manual","localizations":{"ar":{"stringUnit":{"state":"translated","value":a}},"en":{"stringUnit":{"state":"translated","value":e}}}} for k,(a,e) in sorted(S.items())}}
json.dump(cat,open('Lamsa/Localizable.xcstrings','w'),ensure_ascii=False,indent=1)
