for lang,i in (("ar",0),("en",1)):
    import os; os.makedirs(f"Lamsa/{lang}.lproj",exist_ok=True)
    open(f"Lamsa/{lang}.lproj/InfoPlist.strings","w").write(f'"CFBundleDisplayName" = "{["لمسة","Lamsa"][i]}";\n"NFCReaderUsageDescription" = "{["لمسة يستخدم NFC عشان يقرأ البطاقات والملصقات ويكتب عليها","Lamsa uses NFC to read and write tags and stickers"][i]}";\n"NSCameraUsageDescription" = "{["الكاميرا لمسح رمز QR وتحويله لبطاقة NFC","The camera scans QR codes to turn them into NFC tags"][i]}";\n')
